# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

deny contains msg if {
	wl := input[_]
	image_ref := agent_digest_image_refs(wl)[_]
	not regex.match(`^.+@sha256:[a-f0-9]{64}$`, image_ref.image)
	msg := agent_digest_message(wl, image_ref.path)
}

agent_digest_image_refs(wl) := [ref | some i; some set in [{"name": "containers", "items": object.get(pod_spec, "containers", [])}, {"name": "initContainers", "items": object.get(pod_spec, "initContainers", [])}]; c := set.items[i]; ref := {"image": c.image, "path": sprintf("spec.podTemplate.spec.%s[%d].image", [set.name, i])}] if {
	wl.kind in {"Sandbox", "SandboxTemplate"}
	pod_spec := object.get(object.get(wl.spec, "podTemplate", {}), "spec", {})
}

agent_digest_image_refs(wl) := [{"image": wl.spec.workerImage, "path": "spec.workerImage"}] if wl.kind == "WorkerPool"

agent_digest_message(wl, path) := {"alertMessage": sprintf("%v image must be pinned to an exact SHA-256 digest", [wl.kind]), "packagename": "armo_builtins", "failedPaths": [path], "fixPaths": [], "alertScore": 8, "alertObject": {"k8sApiObjects": [wl]}}

# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

deny contains msg if {
	allowed := object.get(data.postureControlInputs, "imageRepositoryAllowList", [])
	count(allowed) > 0
	wl := input[_]
	ref := agent_registry_image_refs(wl)[_]
	not agent_registry_allowed(ref.image, allowed)
	msg := agent_registry_message(wl, ref.path)
}

agent_registry_image_refs(wl) := [ref | some i; some set in [{"name": "containers", "items": object.get(pod_spec, "containers", [])}, {"name": "initContainers", "items": object.get(pod_spec, "initContainers", [])}]; c := set.items[i]; ref := {"image": c.image, "path": sprintf("spec.podTemplate.spec.%s[%d].image", [set.name, i])}] if {
	wl.kind in {"Sandbox", "SandboxTemplate"}
	pod_spec := object.get(object.get(wl.spec, "podTemplate", {}), "spec", {})
}

agent_registry_image_refs(wl) := [{"image": wl.spec.workerImage, "path": "spec.workerImage"}] if wl.kind == "WorkerPool"

agent_registry_allowed(image, allowed) if {
	registry := allowed[_]
	startswith(image, concat("", [registry, "/"]))
}

agent_registry_allowed(image, allowed) if {
	"docker.io" in allowed
	parts := split(image, "/")
	count(parts) > 1
	first := parts[0]
	not contains(first, ".")
	not contains(first, ":")
	first != "localhost"
}

agent_registry_allowed(image, allowed) if {
	"docker.io" in allowed
	count(split(image, "/")) == 1
}

agent_registry_message(wl, path) := {"alertMessage": sprintf("%v image uses a registry outside imageRepositoryAllowList", [wl.kind]), "packagename": "armo_builtins", "failedPaths": [path], "fixPaths": [], "alertScore": 8, "alertObject": {"k8sApiObjects": [wl]}}

# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

deny contains msg if {
	"strict" in object.get(data.postureControlInputs, "agentSandboxEgressMode", ["managed"])
	wl := input[_]
	wl.kind == "SandboxTemplate"
	not agent_sandbox_has_strict_egress(wl)
	msg := {"alertMessage": "Strict mode requires an explicit managed default-deny egress policy; the managed default still permits public internet", "packagename": "armo_builtins", "failedPaths": ["spec.networkPolicy"], "fixPaths": [], "alertScore": 8, "alertObject": {"k8sApiObjects": [wl]}}
}

agent_sandbox_has_strict_egress(wl) if {
	management := object.get(wl, ["spec", "networkPolicyManagement"], null)
	management in {null, "Managed"}
	policy := object.get(wl, ["spec", "networkPolicy"], null)
	is_object(policy)
	egress := object.get(policy, "egress", null)
	is_array(egress)
	count(egress) == 0
}

# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

deny contains msg if {
	maxima := object.get(data.postureControlInputs, "cpu_limit_max", [])
	count(maxima) > 0
	wl := input[_]
	wl.kind == "WorkerPool"
	limit := object.get(wl, ["spec", "template", "resources", "limits", "cpu"], "")
	worker_cpu_limit_invalid(limit, maxima[_])
	msg := worker_ceiling_message(wl, "spec.template.resources.limits.cpu", "CPU")
}

deny contains msg if {
	maxima := object.get(data.postureControlInputs, "memory_limit_max", [])
	count(maxima) > 0
	wl := input[_]
	wl.kind == "WorkerPool"
	limit := object.get(wl, ["spec", "template", "resources", "limits", "memory"], "")
	worker_memory_limit_invalid(limit, maxima[_])
	msg := worker_ceiling_message(wl, "spec.template.resources.limits.memory", "memory")
}

worker_cpu_limit_invalid("", _)

worker_cpu_limit_invalid(limit, maximum) if {
	limit != ""
	worker_cpu_millicores(limit) > worker_cpu_millicores(maximum)
}

worker_memory_limit_invalid("", _)

worker_memory_limit_invalid(limit, maximum) if {
	limit != ""
	worker_memory_bytes(limit) > worker_memory_bytes(maximum)
}

worker_ceiling_message(wl, path, resource) := {"alertMessage": sprintf("Worker Pod %s limit is missing or exceeds the configured ceiling", [resource]), "packagename": "armo_builtins", "failedPaths": [path], "fixPaths": [], "alertScore": 7, "alertObject": {"k8sApiObjects": [wl]}}

worker_cpu_millicores(q) := n if {
	s := sprintf("%v", [q])
	endswith(s, "n")
	n := to_number(trim_suffix(s, "n")) / 1000000
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "u")
	n := to_number(trim_suffix(s, "u")) / 1000
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "m")
	n := to_number(trim_suffix(s, "m"))
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "k")
	n := to_number(trim_suffix(s, "k")) * 1000000
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "M")
	n := to_number(trim_suffix(s, "M")) * 1000000000
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "G")
	n := to_number(trim_suffix(s, "G")) * 1000000000000
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "T")
	n := to_number(trim_suffix(s, "T")) * 1000000000000000
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "P")
	n := to_number(trim_suffix(s, "P")) * 1000000000000000000
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "E")
	n := to_number(trim_suffix(s, "E")) * 1000000000000000000000
} else := n if {
	n := to_number(q) * 1000
}

worker_memory_bytes(q) := n if {
	s := sprintf("%v", [q])
