	n := to_number(trim_suffix(s, "T")) * 1000000000000
} else := n if {
	s := sprintf("%v", [q])
	endswith(s, "P")
	n := to_number(trim_suffix(s, "P")) * 1000000000000000
} else := n if {
	s := sprintf("%v", [q])
